package org.eclipse.kura.linux.watchdog;

import static org.junit.Assert.assertTrue;

import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.kura.linux.watchdog.WatchdogServiceOptions.WatchdogMode;
import org.eclipse.kura.watchdog.WatchdogStatus;
import org.junit.After;
import org.junit.Test;

public class TickFailureResilienceTest {

    private static final long TICK_WAIT_TIMEOUT_MS = 10000;
    private static final int PING_INTERVAL_MS = 50;

    private final CountDownLatch secondTickDelivered = new CountDownLatch(1);
    private final AtomicInteger ticks = new AtomicInteger();
    private FailingTickWatchdogServiceImpl svc;

    @Test
    public void pollTaskKeepsTickingAfterBackendThrowsUnchecked() throws Exception {
        givenServiceWhoseBackendFailsOnFirstTick();

        whenWatchdogServiceIsActivated();

        thenBackendReceivesTickAfterTheFailingOne();
    }

    @After
    public void cleanup() {
        if (this.svc != null) {
            this.svc.deactivate();
        }
    }

    private void givenServiceWhoseBackendFailsOnFirstTick() {
        this.svc = new FailingTickWatchdogServiceImpl();
    }

    private void whenWatchdogServiceIsActivated() {
        final Map<String, Object> properties = new HashMap<>();
        properties.put("enabled", true);
        properties.put("watchdogMode", "direct");
        properties.put("pingInterval", PING_INTERVAL_MS);

        this.svc.activate(properties);
    }

    private void thenBackendReceivesTickAfterTheFailingOne() throws Exception {
        assertTrue(this.secondTickDelivered.await(TICK_WAIT_TIMEOUT_MS, TimeUnit.MILLISECONDS));
    }

    private class FailingTickWatchdogServiceImpl extends HookedWatchdogServiceImpl {

        @Override
        protected WatchdogBackend createBackend(final WatchdogMode mode) {
            if (mode == WatchdogMode.DIRECT) {
                return new FailingTickBackend();
            }
            return super.createBackend(mode);
        }
    }

    private class FailingTickBackend implements WatchdogBackend {

        @Override
        public WatchdogMode getMode() {
            return WatchdogMode.DIRECT;
        }

        @Override
        public boolean configure(WatchdogServiceOptions options, Optional<WatchdogStatus> failedBackendStatus) {
            return true;
        }

        @Override
        public TickResult onTick(Optional<String> failedCriticalComponent) {
            if (TickFailureResilienceTest.this.ticks.incrementAndGet() == 1) {
                throw new IllegalStateException("simulated backend failure");
            }
            TickFailureResilienceTest.this.secondTickDelivered.countDown();
            return TickResult.unchanged();
        }

        @Override
        public void deactivate() {
            // nothing to do
        }

        @Override
        public int getHardwareTimeout() {
            return 0;
        }

        @Override
        public WatchdogStatus getStatus() {
            return WatchdogStatus.builder().build();
        }
    }
}
